import React, {DetailedHTMLProps, InputHTMLAttributes, ReactNode, useState} from 'react'
import SuperInputText from '../../../hw04/common/c1-SuperInputText/SuperInputText'

// тип пропсов обычного инпута
type DefaultInputPropsType = DetailedHTMLProps<InputHTMLAttributes<HTMLInputElement>,
    HTMLInputElement>

// здесь мы говорим что у нашего инпута будут такие же пропсы как у обычного инпута, кроме type
// (чтоб не писать value: string, onChange: ...; они уже все описаны в DefaultInputPropsType)
export type SuperDebouncedInputPropsType = Omit<DefaultInputPropsType, 'type'> & {
    // и + ещё пропсы которых нет в стандартном инпуте
    onChangeText?: (value: string) => void
    onEnter?: () => void
    error?: ReactNode
    spanClassName?: string
} // илм экспортировать тип SuperInputTextPropsType
    & { // плюс специальный пропс SuperPagination
    onDebouncedChange?: (value: string) => void
}

const SuperDebouncedInput: React.FC<SuperDebouncedInputPropsType> = (
    {
        onChangeText,
        onDebouncedChange,

        ...restProps // все остальные пропсы попадут в объект restProps
    }
) => {
    // Указываем тип для таймера явно как number, так как setTimeout в браузере возвращает number.
    // Для Node.js используется `NodeJS.Timeout`, но для React/браузера `number` обычно достаточно.
    const [timerId, setTimerId] = useState<number | undefined>(undefined)

    const onChangeTextCallback = (value: string) => {
        // 1. Вызываем стандартный onChangeText, если он передан
        onChangeText?.(value)

        if (onDebouncedChange) {
            // делает студент

            // 2. Остановить предыдущий таймер
            if (timerId) {
                clearTimeout(timerId)
            }

            // 3. Запустить новый на 1500ms, в котором вызовется функция onDebouncedChange
            const newTimerId = setTimeout(() => {
                onDebouncedChange(value)
            }, 1500) as unknown as number // Приведение к number для совместимости

            // 4. Сохранить новый ID таймера
            setTimerId(newTimerId)
        }
    }

    return (
        <SuperInputText onChangeText={onChangeTextCallback} {...restProps}/>
    )
}

export default SuperDebouncedInput